create table public.billing_invoices(id uuid not null default gen_random_uuid(),tenant_id uuid not null,client_id uuid not null,contract_id uuid not null,month date not null,number text not null,status text not null default 'draft' check(status in ('draft','issued','void')),due_on date not null,subtotal_paise bigint not null,tax_basis_points integer not null check(tax_basis_points between 0 and 10000),tax_paise bigint not null,total_paise bigint not null,adjustment_paise bigint not null default 0,adjustment_reason text not null default '',tax_rule_source text not null,tax_reviewed boolean not null default false,snapshot jsonb not null,issued_at timestamptz,created_at timestamptz not null default now(),created_by uuid not null,row_version integer not null default 0,primary key(tenant_id,id),foreign key(tenant_id,client_id) references public.clients(tenant_id,id),foreign key(tenant_id,contract_id) references public.contracts(tenant_id,id),check(total_paise>=0),unique(tenant_id,number));
create unique index invoice_active_period on public.billing_invoices(tenant_id,contract_id,month) where status<>'void';
create index invoice_client on public.billing_invoices(tenant_id,client_id,created_at desc);
create table public.billing_receipts(id uuid not null default gen_random_uuid(),tenant_id uuid not null,invoice_id uuid not null,kind text not null check(kind in ('payment','credit_note')),amount_paise bigint not null check(amount_paise>0),tds_paise bigint not null default 0 check(tds_paise>=0),reference text not null,received_on date not null,notes text not null,created_at timestamptz not null default now(),created_by uuid not null,primary key(tenant_id,id),foreign key(tenant_id,invoice_id) references public.billing_invoices(tenant_id,id),unique(tenant_id,reference));
create table public.compliance_items(id uuid not null default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),title text not null,category text not null,state text not null default 'Karnataka',due_on date not null,expires_on date,owner text not null,reference text not null default '',notes text not null default '',status text not null default 'pending' check(status in ('pending','submitted','verified')),document_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,row_version integer not null default 0,deleted_at timestamptz,primary key(tenant_id,id),foreign key(tenant_id,document_id) references public.foundation_documents(tenant_id,id));
create table public.recruitment_candidates(id uuid not null default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),full_name text not null,phone text not null,source text not null,status text not null default 'sourced' check(status in ('sourced','screening','documents','verification','ready','rejected','converted')),physical_standards jsonb not null default '{}',screening_notes text not null default '',verification_notes text not null default '',employee_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,row_version integer not null default 0,deleted_at timestamptz,primary key(tenant_id,id),foreign key(tenant_id,employee_id) references public.employees(tenant_id,id));
alter table public.billing_invoices enable row level security;alter table public.billing_receipts enable row level security;alter table public.compliance_items enable row level security;alter table public.recruitment_candidates enable row level security;
revoke all on public.billing_invoices,public.billing_receipts,public.compliance_items,public.recruitment_candidates from anon,authenticated;
grant select on public.billing_invoices,public.billing_receipts to authenticated;grant select,insert,update on public.compliance_items,public.recruitment_candidates to authenticated;
create policy invoice_read on public.billing_invoices for select to authenticated using(sdc_private.is_hr(tenant_id) or sdc_private.is_operator(tenant_id) or (status='issued' and sdc_private.can_contract(tenant_id,contract_id)));
create policy receipt_read on public.billing_receipts for select to authenticated using(exists(select 1 from public.billing_invoices i where i.tenant_id=billing_receipts.tenant_id and i.id=billing_receipts.invoice_id));
create policy compliance_read on public.compliance_items for select to authenticated using(sdc_private.is_hr(tenant_id) or sdc_private.is_operator(tenant_id));
create policy compliance_write on public.compliance_items for all to authenticated using(sdc_private.is_hr(tenant_id)) with check(sdc_private.is_hr(tenant_id));
create policy recruitment_read on public.recruitment_candidates for select to authenticated using(sdc_private.is_hr(tenant_id));
create policy recruitment_write on public.recruitment_candidates for all to authenticated using(sdc_private.is_hr(tenant_id)) with check(sdc_private.is_hr(tenant_id));
create trigger a_stamp before insert or update on public.compliance_items for each row execute function sdc_private.stamp_change();
create trigger z_audit after insert or update on public.compliance_items for each row execute function sdc_private.audit_change();
create trigger a_stamp before insert or update on public.recruitment_candidates for each row execute function sdc_private.stamp_change();
create trigger z_audit after insert or update on public.recruitment_candidates for each row execute function sdc_private.training_audit();
create index compliance_due on public.compliance_items(tenant_id,due_on) where deleted_at is null;
create index recruitment_pipeline on public.recruitment_candidates(tenant_id,status,created_at desc) where deleted_at is null;
create function public.billing_generate(p_tenant uuid,p_contract uuid,p_month date,p_due date,p_tax integer,p_tax_source text,p_reviewed boolean,p_adjustment bigint default 0,p_reason text default '') returns jsonb language plpgsql security definer set search_path='' as $$
declare contract public.contracts;invoice public.billing_invoices;lines jsonb;subtotal bigint;tax bigint;days integer;begin
 if auth.uid() is null or not sdc_private.is_hr(p_tenant) then raise exception 'Only payroll/finance administrators can generate invoices' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_tenant::text,0));
 if extract(day from p_month)<>1 or p_due<p_month or p_tax not between 0 and 10000 or length(trim(p_tax_source))<5 then raise exception 'Enter a valid month, due date and reviewed tax rule source';end if;
 if p_adjustment<>0 and length(trim(p_reason))<5 then raise exception 'Adjustments require a reason';end if;
 select * into contract from public.contracts where tenant_id=p_tenant and id=p_contract and deleted_at is null;
 if not found or contract.starts_on>p_month+interval '1 month'-interval '1 day' or contract.ends_on<p_month then raise exception 'Contract does not cover this billing month';end if;
 if exists(select 1 from public.employee_attendance a join public.sites s on s.tenant_id=a.tenant_id and s.id=a.site_id where a.tenant_id=p_tenant and s.client_id=contract.client_id and a.work_date>=p_month and a.work_date<p_month+interval '1 month' and a.deleted_at is null and a.approval<>'approved') then raise exception 'Approve the client muster before billing';end if;
 if exists(select 1 from public.roster_assignments r join public.sites s on s.tenant_id=r.tenant_id and s.id=r.site_id where r.tenant_id=p_tenant and s.client_id=contract.client_id and r.work_date>=p_month and r.work_date<p_month+interval '1 month' and r.deleted_at is null and r.status='published' and not exists(select 1 from public.employee_attendance a where a.tenant_id=r.tenant_id and a.employee_id=r.employee_id and a.site_id=r.site_id and a.work_date=r.work_date and a.approval='approved' and a.deleted_at is null)) then raise exception 'Published duties are missing approved attendance';end if;
 if exists(select 1 from public.employee_attendance a join public.sites s on s.tenant_id=a.tenant_id and s.id=a.site_id join public.employees e on e.tenant_id=a.tenant_id and e.id=a.employee_id where a.tenant_id=p_tenant and s.client_id=contract.client_id and a.work_date>=p_month and a.work_date<p_month+interval '1 month' and a.status='present' and a.deleted_at is null and not exists(select 1 from public.rate_card_lines r where r.tenant_id=p_tenant and r.contract_id=p_contract and r.grade_id=e.grade_id and r.deleted_at is null)) then raise exception 'A deployed grade is missing its contract rate';end if;
 days=extract(day from p_month+interval '1 month'-interval '1 day');
 select jsonb_agg(to_jsonb(x)),coalesce(sum(x.amount_paise),0) into lines,subtotal from(select a.id as attendance_id,a.work_date,a.employee_id,e.full_name,s.name as site_name,g.name as grade,a.overtime_minutes,r.monthly_rate_paise,r.overtime_hour_paise,round(r.monthly_rate_paise::numeric/days+r.overtime_hour_paise::numeric*a.overtime_minutes/60)::bigint as amount_paise from public.employee_attendance a join public.sites s on s.tenant_id=a.tenant_id and s.id=a.site_id join public.employees e on e.tenant_id=a.tenant_id and e.id=a.employee_id join public.grades g on g.tenant_id=e.tenant_id and g.id=e.grade_id join public.rate_card_lines r on r.tenant_id=a.tenant_id and r.grade_id=e.grade_id and r.contract_id=p_contract and r.deleted_at is null where a.tenant_id=p_tenant and s.client_id=contract.client_id and a.work_date>=greatest(p_month,contract.starts_on) and a.work_date<least((p_month+interval '1 month')::date,contract.ends_on+1) and a.status='present' and a.approval='approved' and a.deleted_at is null)x;
 if lines is null then raise exception 'No approved billable attendance for this month';end if;
 if subtotal+p_adjustment<0 then raise exception 'Adjustment exceeds the invoice value';end if;
 tax=round((subtotal+p_adjustment)::numeric*p_tax/10000);
 insert into public.billing_invoices(tenant_id,client_id,contract_id,month,number,due_on,subtotal_paise,tax_basis_points,tax_paise,total_paise,adjustment_paise,adjustment_reason,tax_rule_source,tax_reviewed,snapshot,created_by) values(p_tenant,contract.client_id,p_contract,p_month,'SDC-'||to_char(p_month,'YYYYMM')||'-'||upper(substr(gen_random_uuid()::text,1,8)),p_due,subtotal,p_tax,tax,subtotal+p_adjustment+tax,p_adjustment,p_reason,p_tax_source,p_reviewed,jsonb_build_object('lines',lines,'days_in_month',days,'contract',to_jsonb(contract),'client',(select to_jsonb(c) from public.clients c where c.tenant_id=p_tenant and c.id=contract.client_id)),auth.uid()) returning * into invoice;
 insert into public.audit_events(tenant_id,actor_user_id,action,entity_type,entity_id,after_data) values(p_tenant,auth.uid(),'generated','billing_invoices',invoice.id,jsonb_build_object('total_paise',invoice.total_paise));return to_jsonb(invoice);
end $$;
create function public.billing_issue(p_tenant uuid,p_invoice uuid,p_version integer,p_action text) returns void language plpgsql security definer set search_path='' as $$ declare i public.billing_invoices;begin
 if auth.uid() is null or not sdc_private.is_hr(p_tenant) then raise exception 'Finance access required' using errcode='42501';end if;
 select * into i from public.billing_invoices where tenant_id=p_tenant and id=p_invoice for update;
 if not found or i.row_version<>p_version then raise exception 'Invoice changed or unavailable';end if;
 if i.status<>'draft' or p_action not in ('issued','void') then raise exception 'Only draft invoices can be issued or voided. Use a credit note for an issued invoice';end if;
 if p_action='issued' and not i.tax_reviewed then raise exception 'Reviewed tax configuration required before issue';end if;
 update public.billing_invoices set status=p_action,issued_at=case when p_action='issued' then now() end,row_version=row_version+1 where tenant_id=p_tenant and id=p_invoice;
 insert into public.audit_events(tenant_id,actor_user_id,action,entity_type,entity_id) values(p_tenant,auth.uid(),p_action,'billing_invoices',p_invoice);end $$;
create function public.billing_receive(p_tenant uuid,p_invoice uuid,p_kind text,p_amount bigint,p_tds bigint,p_reference text,p_date date,p_notes text) returns void language plpgsql security definer set search_path='' as $$ declare i public.billing_invoices;paid bigint;begin
 if auth.uid() is null or not sdc_private.is_hr(p_tenant) then raise exception 'Finance access required' using errcode='42501';end if;
 select * into i from public.billing_invoices where tenant_id=p_tenant and id=p_invoice for update;
 if not found or i.status<>'issued' then raise exception 'Only issued invoices accept receipts or credit notes';end if;
 if p_amount<=0 or p_tds<0 or p_kind not in ('payment','credit_note') or length(trim(p_reference))<3 or length(trim(p_notes))<3 or (p_kind='credit_note' and p_tds<>0) then raise exception 'Enter valid receipt details';end if;
 select coalesce(sum(amount_paise+tds_paise),0) into paid from public.billing_receipts where tenant_id=p_tenant and invoice_id=p_invoice;
 if paid+p_amount+p_tds>i.total_paise then raise exception 'Receipt exceeds outstanding balance';end if;
 insert into public.billing_receipts(tenant_id,invoice_id,kind,amount_paise,tds_paise,reference,received_on,notes,created_by) values(p_tenant,p_invoice,p_kind,p_amount,p_tds,p_reference,p_date,p_notes,auth.uid());
 insert into public.audit_events(tenant_id,actor_user_id,action,entity_type,entity_id,after_data) values(p_tenant,auth.uid(),p_kind,'billing_invoices',p_invoice,jsonb_build_object('amount_paise',p_amount,'tds_paise',p_tds));end $$;
create function public.recruitment_convert(p_tenant uuid,p_candidate uuid,p_grade uuid,p_code text,p_joined date) returns uuid language plpgsql security definer set search_path='' as $$ declare c public.recruitment_candidates;e uuid;begin
 if auth.uid() is null or not sdc_private.is_hr(p_tenant) then raise exception 'HR access required' using errcode='42501';end if;
 select * into c from public.recruitment_candidates where tenant_id=p_tenant and id=p_candidate and deleted_at is null for update;
 if not found or c.status<>'ready' or length(trim(c.verification_notes))<5 then raise exception 'Complete candidate verification and mark ready before conversion';end if;
 insert into public.employees(tenant_id,employee_code,full_name,grade_id,category,status,joined_on,notes) values(p_tenant,p_code,c.full_name,p_grade,'trainee','active',p_joined,'Converted from recruitment candidate '||c.id) returning id into e;
 update public.recruitment_candidates set status='converted',employee_id=e,row_version=row_version+1 where tenant_id=p_tenant and id=p_candidate;return e;end $$;
revoke all on function public.billing_generate(uuid,uuid,date,date,integer,text,boolean,bigint,text),public.billing_issue(uuid,uuid,integer,text),public.billing_receive(uuid,uuid,text,bigint,bigint,text,date,text),public.recruitment_convert(uuid,uuid,uuid,text,date) from public,anon,authenticated;
grant execute on function public.billing_generate(uuid,uuid,date,date,integer,text,boolean,bigint,text),public.billing_issue(uuid,uuid,integer,text),public.billing_receive(uuid,uuid,text,bigint,bigint,text,date,text),public.recruitment_convert(uuid,uuid,uuid,text,date) to authenticated;
